set -eu
cat > /tmp/deliver.restored <<'ANTRIEB_DELIVER_EOF'
#!/bin/sh
set -eu

base=$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)
maildir=$base/Maildir

for box in accounts support general
do
    mkdir -p "$maildir/$box/new"
done
mkdir -p "$maildir/tmp"

umask 077
tmp=$(mktemp "$maildir/tmp/deliver.$(date +%s).$$.XXXXXX")
trap 'rm -f -- "$tmp"' 0
trap 'exit 1' 1 2 3 15

cat > "$tmp"

department=$(LC_ALL=C awk '
function lower(s,    out, i, c, upper, lowerchars) {
    upper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    lowerchars = "abcdefghijklmnopqrstuvwxyz"
    out = ""
    for (i = 1; i <= length(s); i++) {
        c = substr(s, i, 1)
        if (index(upper, c))
            c = substr(lowerchars, index(upper, c), 1)
        out = out c
    }
    return out
}
function trim(s) {
    sub(/^[[:space:]]+/, "", s)
    sub(/[[:space:]]+$/, "", s)
    return s
}
function finish_header(    v) {
    if (!in_department)
        return
    v = lower(trim(value))
    in_department = 0
    if (v == "accounts" || v == "support") {
        print v
        exit
    }
}
{
    line = $0
    sub(/\r$/, "", line)
    if (line == "") {
        finish_header()
        exit
    }
    if (line ~ /^[ \t]/) {
        if (in_department) {
            continuation = line
            sub(/^[ \t]+/, "", continuation)
            value = value " " continuation
        }
        next
    }
    finish_header()
    colon = index(line, ":")
    in_department = 0
    value = ""
    if (colon > 0 && lower(substr(line, 1, colon - 1)) == "x-department") {
        in_department = 1
        value = substr(line, colon + 1)
    }
}
END {
    finish_header()
}
' "$tmp")

case $department in
    accounts|support) destination=$department ;;
    *) destination=general ;;
esac

name=$(basename -- "$tmp")
mv -- "$tmp" "$maildir/$destination/new/$name"
trap - 0 1 2 3 15
ANTRIEB_DELIVER_EOF
sh -n /tmp/deliver.restored
install -o root -g root -m 0755 /tmp/deliver.restored /srv/legacy2/mail-filter-routing/bin/deliver
rm -f /tmp/deliver.restored
printf '%s\n' 'installed:'
ls -l /srv/legacy2/mail-filter-routing/bin/deliver
sha256sum /srv/legacy2/mail-filter-routing/bin/deliver
sh -n /srv/legacy2/mail-filter-routing/bin/deliver

